{{-- The figure strip under a page head. items: [['label' => 'Characters', 'value' => '1,284', 'unit' => 'played']]. Each figure is a term and its value in a list of its own. An item's `icon` key names its glyph (null for none); without the key App\View\Glyph picks one from the label. --}}
@props(['items'])
<section @class(['week', 'n6' => count($items) === 6, 'n7' => count($items) === 7]) aria-label="Totals">@foreach ($items as $item)@php($glyph = array_key_exists('icon', $item) ? $item['icon'] : \App\View\Glyph::for($item['label']))<dl><dt>@if ($glyph)<x-icon :name="$glyph" />@endif{{ $item['label'] }}</dt><dd>{{ $item['value'] }}@isset($item['unit'])<small>{{ $item['unit'] }}</small>@endisset</dd></dl>@endforeach</section>
